#pragma once

#include "curvy/imagetrace.h"

#include <newui/frame.h>

#include <string>

namespace curvy {

    // The Image Trace options dialog (Resources/tracedialog.newui, generated by tools/gen_newui.py): how many colors, how large the
    // picture is traced, how small a speck may be, how smooth the curves are and whether a white background is left out. Runs
    // modally over `owner` and keeps what was chosen in `options`.
    // @reflect ignore=true
    class TraceDialog {
    public:
        // True when the user pressed Trace (options then holds the choices, brought into range); false on Cancel / close or if the
        // dialog file cannot be loaded. `options` is the starting state either way.
        static bool run(newui::Frame& owner, TraceOptions& options, const std::string& picture);

        // How a smoothness choice (0 tight, 1 normal, 2 smooth) fits curves, and back.
        static double toleranceFor(int smoothness);
        static int smoothnessFor(double tolerance);

        // Headless self-test (sketch.exe --check-newdoc runs it too): loads the dialog without showing it and drives the controls.
        // Returns the number of failed checks.
        static int check();
    };

}
